// Each locale supplies complete copy; the mapper keeps semantic keys identical.
function teamCopy(copy: {
  title: string; scope: string; message: string; send: string; review: string; confirm: string; pause: string;
  routines: string; history: string; revise: string; schedule: string; daily: string; weekly: string; once: string;
  time: string; zone: string; date: string; days: string; occurrences: string; tokens: string; readOnly: string;
  next: string; proposed: string; confirmed: string; unread: string; host: string; awake: string; wake: string;
  hostLimits: string; usage: string; unavailable: string; billing: string; children: string; artifacts: string; empty: string;
}) {
  return {
    'home.teamTitle': copy.title, 'home.teamScope': copy.scope, 'home.teamMessage': copy.message, 'home.teamSend': copy.send,
    'home.teamReview': copy.review, 'home.teamConfirm': copy.confirm, 'home.teamPause': copy.pause, 'home.teamRoutines': copy.routines,
    'home.teamHistory': copy.history, 'home.teamRevise': copy.revise, 'home.teamSchedule': copy.schedule, 'home.teamDaily': copy.daily,
    'home.teamWeekly': copy.weekly, 'home.teamOnce': copy.once, 'home.teamTime': copy.time, 'home.teamZone': copy.zone,
    'home.teamDate': copy.date, 'home.teamDays': copy.days, 'home.teamOccurrences': copy.occurrences, 'home.teamTokens': copy.tokens,
    'home.teamReadOnly': copy.readOnly, 'home.teamNext': copy.next, 'home.teamProposed': copy.proposed, 'home.teamConfirmed': copy.confirmed,
    'home.teamUnread': copy.unread, 'home.teamHost': copy.host, 'home.teamAwake': copy.awake, 'home.teamWake': copy.wake,
    'home.teamHostLimits': copy.hostLimits, 'home.teamUsage': copy.usage, 'home.teamUnavailable': copy.unavailable,
    'home.teamBilling': copy.billing, 'home.teamChildren': copy.children, 'home.teamArtifacts': copy.artifacts, 'home.teamEmpty': copy.empty,
  };
}
